class Solution {
public:
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        unordered_map<int, int> inMap;
        for (int i = 0; i < (int)inorder.size(); i++) inMap[inorder[i]] = i;
        int preIdx = 0;
        return helper(preorder, inMap, preIdx, 0, (int)inorder.size() - 1);
    }
private:
    TreeNode* helper(vector<int>& preorder, unordered_map<int, int>& inMap, int& preIdx, int left, int right) {
        if (left > right) return nullptr;
        int rootVal = preorder[preIdx++];
        TreeNode* root = new TreeNode(rootVal);
        int mid = inMap[rootVal];
        root->left = helper(preorder, inMap, preIdx, left, mid - 1);
        root->right = helper(preorder, inMap, preIdx, mid + 1, right);
        return root;
    }
};

class Solution {
    private int preIdx = 0;
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        Map<Integer, Integer> inMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) inMap.put(inorder[i], i);
        return helper(preorder, inMap, 0, inorder.length - 1);
    }
    private TreeNode helper(int[] preorder, Map<Integer, Integer> inMap, int left, int right) {
        if (left > right) return null;
        int rootVal = preorder[preIdx++];
        TreeNode root = new TreeNode(rootVal);
        int mid = inMap.get(rootVal);
        root.left = helper(preorder, inMap, left, mid - 1);
        root.right = helper(preorder, inMap, mid + 1, right);
        return root;
    }
}

var buildTree = function(preorder, inorder) {
    const inMap = new Map();
    for (let i = 0; i < inorder.length; i++) inMap.set(inorder[i], i);
    let preIdx = 0;
    function helper(left, right) {
        if (left > right) return null;
        const rootVal = preorder[preIdx++];
        const root = new TreeNode(rootVal);
        const mid = inMap.get(rootVal);
        root.left = helper(left, mid - 1);
        root.right = helper(mid + 1, right);
